-- Curated local dataset for a lively, real API walkthrough.
-- The Node wrapper checks the database name before executing this file.
-- It is intentionally not a migration and must never run in production.

BEGIN;
SET LOCAL client_encoding = 'UTF8';

CREATE TEMP TABLE seed_users (email TEXT PRIMARY KEY, id INTEGER NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE seed_books (isbn TEXT PRIMARY KEY, id INTEGER NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE seed_corners (key TEXT PRIMARY KEY, id UUID NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE seed_listings (key TEXT PRIMARY KEY, id INTEGER NOT NULL, user_id INTEGER NOT NULL, book_id INTEGER NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE seed_conversations (key TEXT PRIMARY KEY, id BIGINT NOT NULL, user_a INTEGER NOT NULL, user_b INTEGER NOT NULL) ON COMMIT DROP;

DO $seed_users$
DECLARE item JSONB; user_id INTEGER;
BEGIN
  FOR item IN SELECT jsonb_array_elements($users$
    [
      {"email":"test@entrelibros.com","name":"Cuenta de prueba","alias":"test.entrelibros","city":"Buenos Aires","neighborhood":"Almagro","description":"Cuenta principal para recorrer la demo: descubre libros, conversa y concreta intercambios reales.","interests":["fiction","classics","contemporary"],"visibility":"neighborhood","lat":-34.605,"lon":-58.415,"photo":"https://randomuser.me/api/portraits/women/47.jpg"},
      {"email":"lucia@entrelibros.com","name":"Lucía Benítez","alias":"lucia.benitez","city":"Buenos Aires","neighborhood":"Almagro","description":"Lectora curiosa que arma clubes pequeños alrededor de novelas familiares y contemporáneas.","interests":["fiction","romance","classics"],"visibility":"neighborhood","lat":-34.605,"lon":-58.415,"photo":"https://randomuser.me/api/portraits/women/44.jpg"},
      {"email":"martin@entrelibros.com","name":"Martín Quiroga","alias":"martin.quiroga","city":"Buenos Aires","neighborhood":"Villa Urquiza","description":"Busca ciencia ficción, ensayo y conversaciones largas sobre cómo cambian las ciudades.","interests":["science-fiction","history","philosophy"],"visibility":"city","lat":-34.571,"lon":-58.485,"photo":"https://randomuser.me/api/portraits/men/32.jpg"},
      {"email":"sofia@entrelibros.com","name":"Sofía Ledesma","alias":"sofia.ledesma","city":"Buenos Aires","neighborhood":"Belgrano","description":"Intercambia lecturas contemporáneas y prefiere encontrarse en bibliotecas tranquilas.","interests":["fiction","romance","contemporary"],"visibility":"neighborhood","lat":-34.562,"lon":-58.458,"photo":"https://randomuser.me/api/portraits/women/65.jpg"},
      {"email":"clara@entrelibros.com","name":"Clara Benítez","alias":"clara.benitez","city":"Buenos Aires","neighborhood":"Palermo","description":"Organiza lecturas compartidas y cuida una pequeña biblioteca de barrio.","interests":["fiction","classics","poetry"],"visibility":"neighborhood","lat":-34.585,"lon":-58.414,"photo":"https://randomuser.me/api/portraits/women/12.jpg"},
      {"email":"tomas@entrelibros.com","name":"Tomás Ferreyra","alias":"tomas.ferreyra","city":"Buenos Aires","neighborhood":"Chacarita","description":"Fan de la fantasía y la ciencia ficción; coordina intercambios en persona.","interests":["fantasy","science-fiction","adventure"],"visibility":"city","lat":-34.587,"lon":-58.452,"photo":"https://randomuser.me/api/portraits/men/75.jpg"},
      {"email":"julieta@entrelibros.com","name":"Julieta Ríos","alias":"julieta.rios","city":"Buenos Aires","neighborhood":"Caballito","description":"Lee narrativa histórica y recomienda títulos para largas tardes de domingo.","interests":["history","fiction","classics"],"visibility":"neighborhood","lat":-34.618,"lon":-58.437,"photo":"https://randomuser.me/api/portraits/women/31.jpg"},
      {"email":"pablo@entrelibros.com","name":"Pablo Acosta","alias":"pablo.acosta","city":"Buenos Aires","neighborhood":"Villa Crespo","description":"Colecciona novelas breves, cómics y autores nuevos de América Latina.","interests":["fiction","literary-fiction","comedy"],"visibility":"city","lat":-34.599,"lon":-58.443,"photo":"https://randomuser.me/api/portraits/men/41.jpg"},
      {"email":"valentina@entrelibros.com","name":"Valentina Costa","alias":"valentina.costa","city":"Buenos Aires","neighborhood":"San Telmo","description":"Busca poesía, memorias y ediciones ilustradas para regalar o intercambiar.","interests":["poetry","memoir","art"],"visibility":"neighborhood","lat":-34.621,"lon":-58.374,"photo":"https://randomuser.me/api/portraits/women/49.jpg"},
      {"email":"diego@entrelibros.com","name":"Diego Molina","alias":"diego.molina","city":"Buenos Aires","neighborhood":"Parque Patricios","description":"Lector de policiales y crónicas urbanas; siempre llega con una recomendación.","interests":["thriller","crime","history"],"visibility":"city","lat":-34.637,"lon":-58.405,"photo":"https://randomuser.me/api/portraits/men/46.jpg"},
      {"email":"ana@entrelibros.com","name":"Ana Lectura","alias":"ana.lectura","city":"Buenos Aires","neighborhood":"Colegiales","description":"Combina literatura infantil, viajes y clubes de lectura con familias del barrio.","interests":["children","travel","fiction"],"visibility":"neighborhood","lat":-34.575,"lon":-58.451,"photo":"https://randomuser.me/api/portraits/women/68.jpg"},
      {"email":"nicolas@entrelibros.com","name":"Nicolás Reyes","alias":"nicolas.reyes","city":"La Plata","neighborhood":"Tolosa","description":"Participa a distancia y coordina envíos cuando encuentra una edición difícil.","interests":["science-fiction","history","technology"],"visibility":"city","lat":-34.903,"lon":-57.955,"photo":"https://randomuser.me/api/portraits/men/52.jpg"},
      {"email":"elena@entrelibros.com","name":"Elena Duarte","alias":"elena.duarte","city":"Buenos Aires","neighborhood":"Núñez","description":"Disfruta la narrativa latinoamericana y las conversaciones que siguen a una lectura.","interests":["fiction","latin-america","romance"],"visibility":"neighborhood","lat":-34.548,"lon":-58.461,"photo":"https://randomuser.me/api/portraits/women/26.jpg"}
    ]$users$::JSONB)
  LOOP
    INSERT INTO users (name, alias, email, password, role, language, profile_description, profile_visibility, location_visibility, interests, country, city, neighborhood, location, search_radius, profile_photo_url)
    VALUES (item->>'name', item->>'alias', item->>'email', '$2b$10$YhaF/tEVbS.vLxZL0by4xuNvzWCas3OCxJaP/I3wCPSgmki4N5iby', 'user', 'es', item->>'description', 'public', item->>'visibility', ARRAY(SELECT jsonb_array_elements_text(item->'interests')), 'Argentina', item->>'city', item->>'neighborhood', ST_SetSRID(ST_MakePoint((item->>'lon')::DOUBLE PRECISION, (item->>'lat')::DOUBLE PRECISION), 4326)::geography, 15, item->>'photo')
    ON CONFLICT (email) DO UPDATE SET name = EXCLUDED.name, alias = EXCLUDED.alias, password = EXCLUDED.password, profile_description = EXCLUDED.profile_description, profile_visibility = EXCLUDED.profile_visibility, location_visibility = EXCLUDED.location_visibility, interests = EXCLUDED.interests, country = EXCLUDED.country, city = EXCLUDED.city, neighborhood = EXCLUDED.neighborhood, location = EXCLUDED.location, search_radius = EXCLUDED.search_radius, profile_photo_url = EXCLUDED.profile_photo_url
    RETURNING id INTO user_id;
    INSERT INTO seed_users (email, id) VALUES (item->>'email', user_id) ON CONFLICT (email) DO UPDATE SET id = EXCLUDED.id;
  END LOOP;
END $seed_users$;

DO $seed_books$
DECLARE item JSONB; book_id INTEGER;
BEGIN
  FOR item IN SELECT jsonb_array_elements($books$
    [
      {"isbn":"9788437604794","title":"Rayuela","author":"Julio Cortázar","publisher":"Alfaguara","year":1963},{"isbn":"9788437604947","title":"Cien años de soledad","author":"Gabriel García Márquez","publisher":"Debolsillo","year":1967},{"isbn":"9788499890944","title":"1984","author":"George Orwell","publisher":"Debolsillo","year":1949},{"isbn":"9788478887194","title":"El principito","author":"Antoine de Saint-Exupéry","publisher":"Salamandra","year":1943},{"isbn":"9788491050299","title":"Orgullo y prejuicio","author":"Jane Austen","publisher":"Austral","year":1813},{"isbn":"9788437604944","title":"Crónica de una muerte anunciada","author":"Gabriel García Márquez","publisher":"Debolsillo","year":1981},{"isbn":"9788420633111","title":"El Aleph","author":"Jorge Luis Borges","publisher":"Alianza Editorial","year":1949},{"isbn":"9788408172179","title":"La sombra del viento","author":"Carlos Ruiz Zafón","publisher":"Planeta","year":2001},{"isbn":"9788416517271","title":"Los siete maridos de Evelyn Hugo","author":"Taylor Jenkins Reid","publisher":"Umbriel","year":2017},{"isbn":"9788497592208","title":"La casa de los espíritus","author":"Isabel Allende","publisher":"Debolsillo","year":1982},{"isbn":"9788401337208","title":"El nombre del viento","author":"Patrick Rothfuss","publisher":"Plaza & Janés","year":2008},{"isbn":"9788499926223","title":"Sapiens: de animales a dioses","author":"Yuval Noah Harari","publisher":"Debate","year":2011},{"isbn":"9788498382372","title":"Coraline","author":"Neil Gaiman","publisher":"Salamandra","year":2002},{"isbn":"9788445000760","title":"La mano izquierda de la oscuridad","author":"Ursula K. Le Guin","publisher":"Minotauro","year":1969},{"isbn":"9788417347087","title":"El problema de los tres cuerpos","author":"Cixin Liu","publisher":"Nova","year":2008},{"isbn":"9788497592457","title":"El amor en los tiempos del cólera","author":"Gabriel García Márquez","publisher":"Debolsillo","year":1985},{"isbn":"9788497594257","title":"Fahrenheit 451","author":"Ray Bradbury","publisher":"Debolsillo","year":1953},{"isbn":"9788497592444","title":"Persépolis","author":"Marjane Satrapi","publisher":"Reservoir Books","year":2000},{"isbn":"9788417860791","title":"El infinito en un junco","author":"Irene Vallejo","publisher":"Siruela","year":2019},{"isbn":"9788439722464","title":"Los detectives salvajes","author":"Roberto Bolaño","publisher":"Anagrama","year":1998},{"isbn":"9788483468680","title":"La carretera","author":"Cormac McCarthy","publisher":"Debolsillo","year":2006},{"isbn":"9788439722341","title":"El dios de las pequeñas cosas","author":"Arundhati Roy","publisher":"Anagrama","year":1997},{"isbn":"9788418015855","title":"Piranesi","author":"Susanna Clarke","publisher":"Alianza","year":2020},{"isbn":"9788497595728","title":"La vegetariana","author":"Han Kang","publisher":"Rata","year":2007},{"isbn":"9788439724703","title":"El año del pensamiento mágico","author":"Joan Didion","publisher":"Mondadori","year":2005},{"isbn":"9788413621658","title":"La biblioteca de la medianoche","author":"Matt Haig","publisher":"AdN","year":2020},{"isbn":"9788413140326","title":"La mujer en la ventana","author":"A.J. Finn","publisher":"Alfaguara","year":2019},{"isbn":"9788466347994","title":"La ridícula idea de no volver a verte","author":"Rosa Montero","publisher":"Seix Barral","year":2013},{"isbn":"9788423360793","title":"Los asquerosos","author":"Santiago Lorenzo","publisher":"Blackie Books","year":2018},{"isbn":"9788423354273","title":"Todo esto te daré","author":"Dolores Redondo","publisher":"Destino","year":2016}
    ]$books$::JSONB)
  LOOP
    SELECT id INTO book_id FROM books WHERE isbn = item->>'isbn' LIMIT 1;
    IF book_id IS NULL THEN
      INSERT INTO books (title, author, isbn, publisher, published_year, verified, language, format, cover_url)
      VALUES (item->>'title', item->>'author', item->>'isbn', item->>'publisher', (item->>'year')::INTEGER, true, 'es', 'paperback', 'https://covers.openlibrary.org/b/isbn/' || (item->>'isbn') || '-L.jpg?default=false') RETURNING id INTO book_id;
    ELSE
      UPDATE books SET title = item->>'title', author = item->>'author', publisher = item->>'publisher', published_year = (item->>'year')::INTEGER, verified = true, language = 'es', format = 'paperback', cover_url = 'https://covers.openlibrary.org/b/isbn/' || (item->>'isbn') || '-L.jpg?default=false' WHERE id = book_id;
    END IF;
    INSERT INTO seed_books (isbn, id) VALUES (item->>'isbn', book_id) ON CONFLICT (isbn) DO UPDATE SET id = EXCLUDED.id;
  END LOOP;
END $seed_books$;

DO $seed_corners$
DECLARE item RECORD; owner_id INTEGER;
BEGIN
  FOR item IN SELECT * FROM jsonb_to_recordset($corners$
    [
      {"key":"palermo","id":"4a089a74-4dfc-4531-a04c-883d3cd2233a","name":"Biblioteca de Barrio Palermo","host":"Clara Benítez","owner":"clara@entrelibros.com","rules":"Dejá un libro en buen estado y llevate otro que te acompañe.","schedule":"Miércoles de 17:00 a 20:00","street":"Güemes","number":"3300","postal":"1425","lat":-34.585,"lon":-58.414,"photo":"https://images.unsplash.com/photo-1507842217343-583bb7270b66?auto=format&fit=crop&w=1200&q=85"},{"key":"chacarita","id":"5a089a74-4dfc-4531-a04c-883d3cd2233a","name":"Rincón de Lectura Chacarita","host":"Tomás Ferreyra","owner":"tomas@entrelibros.com","rules":"Intercambios coordinados con respeto y aviso previo.","schedule":"Sábados de 10:00 a 13:00","street":"Jorge Newbery","number":"1700","postal":"1426","lat":-34.587,"lon":-58.452,"photo":"https://images.unsplash.com/photo-1521587760476-6c12a4b040da?auto=format&fit=crop&w=1200&q=85"},{"key":"caballito","id":"6a089a74-4dfc-4531-a04c-883d3cd2233a","name":"Mesa de Historia Caballito","host":"Julieta Ríos","owner":"julieta@entrelibros.com","rules":"Conversamos sobre historia y dejamos espacio para nuevas voces.","schedule":"Jueves de 18:00 a 21:00","street":"Rivadavia","number":"5200","postal":"1424","lat":-34.618,"lon":-58.437,"photo":"https://images.unsplash.com/photo-1495446815901-a7297e633e8d?auto=format&fit=crop&w=1200&q=85"},{"key":"villa-crespo","id":"7a089a74-4dfc-4531-a04c-883d3cd2233a","name":"Café de los Libros Villa Crespo","host":"Pablo Acosta","owner":"pablo@entrelibros.com","rules":"Punto de encuentro vecinal; confirmá la visita antes de acercarte.","schedule":"Viernes de 16:00 a 19:00","street":"Loyola","number":"500","postal":"1414","lat":-34.599,"lon":-58.443,"photo":"https://images.unsplash.com/photo-1526243741027-444d633d7365?auto=format&fit=crop&w=1200&q=85"},{"key":"san-telmo","id":"8a089a74-4dfc-4531-a04c-883d3cd2233a","name":"Patio de Lectura San Telmo","host":"Valentina Costa","owner":"valentina@entrelibros.com","rules":"Traé una lectura y una pregunta para compartir.","schedule":"Domingos de 11:00 a 14:00","street":"Defensa","number":"900","postal":"1065","lat":-34.621,"lon":-58.374,"photo":"https://images.unsplash.com/photo-1526243741027-444d633d7365?auto=format&fit=crop&w=1200&q=85"},{"key":"parque-patricios","id":"9a089a74-4dfc-4531-a04c-883d3cd2233a","name":"Mesa Literaria Parque Patricios","host":"Diego Molina","owner":"diego@entrelibros.com","rules":"Mesa abierta para compartir crónicas y coordinar intercambios.","schedule":"Sábados de 15:00 a 18:00","street":"Av. Caseros","number":"3200","postal":"1263","lat":-34.637,"lon":-58.405,"photo":"https://images.unsplash.com/photo-1526243741027-444d633d7365?auto=format&fit=crop&w=1200&q=85"},{"key":"colegiales","id":"aa089a74-4dfc-4531-a04c-883d3cd2233a","name":"Rincón Familiar Colegiales","host":"Ana Lectura","owner":"ana@entrelibros.com","rules":"Un espacio amable para lecturas infantiles y familias.","schedule":"Sábados de 10:30 a 12:30","street":"Álvarez Thomas","number":"900","postal":"1427","lat":-34.575,"lon":-58.451,"photo":"https://images.unsplash.com/photo-1521587760476-6c12a4b040da?auto=format&fit=crop&w=1200&q=85"},{"key":"nunez","id":"ba089a74-4dfc-4531-a04c-883d3cd2233a","name":"Club del Río Núñez","host":"Elena Duarte","owner":"elena@entrelibros.com","rules":"Leemos narrativa latinoamericana y cuidamos la privacidad del barrio.","schedule":"Martes de 18:30 a 20:30","street":"Arribeños","number":"2400","postal":"1428","lat":-34.548,"lon":-58.461,"photo":"https://images.unsplash.com/photo-1507842217343-583bb7270b66?auto=format&fit=crop&w=1200&q=85"}
    ]$corners$::JSONB) AS x(key TEXT, id UUID, name TEXT, host TEXT, owner TEXT, rules TEXT, schedule TEXT, street TEXT, number TEXT, postal TEXT, lat NUMERIC, lon NUMERIC, photo TEXT)
  LOOP
    SELECT id INTO owner_id FROM seed_users WHERE email = item.owner;
    INSERT INTO community_corners (id, name, scope, host_alias, internal_contact, rules, schedule, visibility_preference, address_street, address_number, address_postal_code, status, draft, consent, location, editorial_status, owner_id)
    VALUES (item.id, item.name, 'public', item.host, item.key || '@entrelibros.com', item.rules, item.schedule, 'approximate', item.street, item.number, item.postal, 'active', false, true, ST_SetSRID(ST_MakePoint(item.lon, item.lat), 4326)::geography, 'approved', owner_id)
    ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, host_alias = EXCLUDED.host_alias, internal_contact = EXCLUDED.internal_contact, rules = EXCLUDED.rules, schedule = EXCLUDED.schedule, address_street = EXCLUDED.address_street, address_number = EXCLUDED.address_number, address_postal_code = EXCLUDED.address_postal_code, status = EXCLUDED.status, draft = EXCLUDED.draft, consent = EXCLUDED.consent, location = EXCLUDED.location, editorial_status = EXCLUDED.editorial_status, owner_id = EXCLUDED.owner_id;
    INSERT INTO seed_corners (key, id) VALUES (item.key, item.id) ON CONFLICT (key) DO UPDATE SET id = EXCLUDED.id;
    INSERT INTO community_corner_photos (id, corner_id, external_id, url, is_primary) SELECT gen_random_uuid(), item.id, 'local-demo-' || item.key, item.photo, true WHERE NOT EXISTS (SELECT 1 FROM community_corner_photos WHERE corner_id = item.id AND is_primary = true);
    INSERT INTO community_corner_metrics (corner_id, total_exchanges, weekly_exchanges, last_activity_at) VALUES (item.id, 12, 4, NOW() - INTERVAL '45 minutes') ON CONFLICT (corner_id) DO UPDATE SET total_exchanges = EXCLUDED.total_exchanges, weekly_exchanges = EXCLUDED.weekly_exchanges, last_activity_at = EXCLUDED.last_activity_at, updated_at = NOW();
  END LOOP;
END $seed_corners$;

DO $seed_listings$
DECLARE item RECORD; v_listing_id INTEGER; v_corner_id UUID;
BEGIN
  FOR item IN
    WITH numbered_users AS (SELECT email, id, ROW_NUMBER() OVER (ORDER BY email) - 1 AS position FROM seed_users), numbered_books AS (SELECT isbn, id, ROW_NUMBER() OVER (ORDER BY isbn) - 1 AS position FROM seed_books)
    SELECT user_row.email, user_row.id AS user_id, book_row.isbn, book_row.id AS book_id, slot.position AS slot, CASE slot.position WHEN 0 THEN 'offer' WHEN 1 THEN 'offer' ELSE 'want' END AS type, CASE slot.position WHEN 0 THEN 'very_good' WHEN 1 THEN 'good' ELSE NULL END AS condition, slot.position < 2 AS trade, slot.position = 1 AS sale, CASE WHEN slot.position = 1 THEN 4500 + user_row.position * 500 ELSE NULL END AS price, CASE WHEN slot.position < 2 THEN (ARRAY['palermo','chacarita','caballito','villa-crespo','san-telmo','parque-patricios','colegiales','nunez'])[1 + (user_row.position % 8)] ELSE NULL END AS corner
    FROM numbered_users user_row CROSS JOIN (VALUES (0), (1), (2)) AS slot(position) JOIN numbered_books book_row ON book_row.position = ((user_row.position * 3 + slot.position) % 30)
  LOOP
    v_corner_id := CASE WHEN item.corner IS NULL THEN NULL ELSE (SELECT id FROM seed_corners WHERE key = item.corner) END;
    SELECT listing.id INTO v_listing_id FROM book_listings listing WHERE listing.user_id = item.user_id AND listing.book_id = item.book_id AND listing.type::TEXT = item.type AND listing.is_draft = false AND COALESCE(listing.corner_id, '') = COALESCE(v_corner_id::TEXT, '') LIMIT 1;
    IF v_listing_id IS NULL THEN
      INSERT INTO book_listings (user_id, book_id, status, type, description, condition, sale, trade, availability, price_amount, price_currency, delivery_in_person, delivery_near_book_corner, is_draft, corner_id, content_consent, image_consent, rules_consent)
      VALUES (item.user_id, item.book_id, 'available', item.type::publication_type, CASE item.slot WHEN 0 THEN 'Ejemplar muy cuidado para intercambiar; me interesa saber qué conversación abre en otro barrio.' WHEN 1 THEN 'Lectura con historia y algunas marcas. Se puede retirar en persona o coordinar en el rincón del barrio.' ELSE 'Busco este título para el próximo encuentro; agradezco propuestas con foto, estado y punto de entrega.' END, item.condition::publication_condition, item.sale, item.trade, 'public', item.price, CASE WHEN item.price IS NULL THEN NULL ELSE 'ARS' END, true, item.corner IS NOT NULL, false, v_corner_id::TEXT, true, true, true) RETURNING id INTO v_listing_id;
    END IF;
    INSERT INTO seed_listings (key, id, user_id, book_id) VALUES (item.email || '|' || item.isbn || '|' || item.type || '|' || COALESCE(item.corner, 'none'), v_listing_id, item.user_id, item.book_id) ON CONFLICT (key) DO UPDATE SET id = EXCLUDED.id, user_id = EXCLUDED.user_id, book_id = EXCLUDED.book_id;
  END LOOP;
  INSERT INTO book_listing_images (book_listing_id, url, is_primary, source, metadata) SELECT listing.id, book.cover_url, true, 'open-library', jsonb_build_object('localDemo', true, 'isbn', book.isbn, 'role', 'cover') FROM seed_listings seeded JOIN book_listings listing ON listing.id = seeded.id JOIN books book ON book.id = listing.book_id WHERE book.cover_url IS NOT NULL AND NOT EXISTS (SELECT 1 FROM book_listing_images image WHERE image.book_listing_id = listing.id AND image.is_primary = true);
  INSERT INTO book_listing_images (book_listing_id, url, is_primary, source, metadata) SELECT listing.id, CASE MOD(listing.id, 4) WHEN 0 THEN 'https://images.unsplash.com/photo-1512820790803-83ca734da794?auto=format&fit=crop&w=1200&q=85' WHEN 1 THEN 'https://images.unsplash.com/photo-1495446815901-a7297e633e8d?auto=format&fit=crop&w=1200&q=85' WHEN 2 THEN 'https://images.unsplash.com/photo-1521587760476-6c12a4b040da?auto=format&fit=crop&w=1200&q=85' ELSE 'https://images.unsplash.com/photo-1507842217343-583bb7270b66?auto=format&fit=crop&w=1200&q=85' END, false, 'unsplash', jsonb_build_object('localDemo', true, 'role', 'context') FROM seed_listings seeded JOIN book_listings listing ON listing.id = seeded.id WHERE NOT EXISTS (SELECT 1 FROM book_listing_images image WHERE image.book_listing_id = listing.id AND image.metadata->>'role' = 'context');
END $seed_listings$;

DO $seed_social$
DECLARE item RECORD; v_listing_id INTEGER;
BEGIN
  FOR item IN SELECT * FROM (VALUES
    ('test@entrelibros.com','Hoy arranco el recorrido de EntreLibros: busco una novela que me lleve a conocer un rincón nuevo.'),('lucia@entrelibros.com','¿Qué libro te cambió una conversación? Esta semana llevamos nuestras respuestas al encuentro de Almagro.'),('martin@entrelibros.com','Traigo ciencia ficción y una pregunta: ¿qué ciudad imaginaria visitarían primero?'),('sofia@entrelibros.com','Propongo una ronda de recomendaciones de menos de 250 páginas para volver a leer en el tren.'),('clara@entrelibros.com','En Palermo dejamos una mesa libre para dedicatorias: contá por qué elegiste ese libro para otra persona.'),('tomas@entrelibros.com','El sábado en Chacarita comparamos mundos fantásticos. Hay mate, mapas y ganas de descubrir autores nuevos.'),('julieta@entrelibros.com','Para la Mesa de Historia: elegí una escena que te haya cambiado la forma de mirar la ciudad.'),('pablo@entrelibros.com','Busco cómics y novelas breves que se puedan discutir en un café sin mirar el reloj.'),('valentina@entrelibros.com','¿Qué ilustración guardarían como recuerdo de una lectura? Este domingo lo conversamos en San Telmo.'),('diego@entrelibros.com','Tengo una crónica urbana para quien quiera caminar el barrio con otros ojos.'),('ana@entrelibros.com','El rincón familiar abre con una consigna simple: cada persona trae un personaje que le gustaría invitar a merendar.'),('nicolas@entrelibros.com','Desde La Plata me sumo a los intercambios a distancia: puedo coordinar envío y recomendar ciencia ficción argentina.'),('elena@entrelibros.com','En Núñez armamos una lista colectiva de finales que merecen quedarse conversando después de la última página.')
  ) AS story(email, body)
  LOOP
    SELECT id INTO v_listing_id FROM seed_listings WHERE user_id = (SELECT id FROM seed_users WHERE email = item.email) ORDER BY id LIMIT 1;
    INSERT INTO community_stories (user_id, body, image_url, book_listing_id) SELECT user_row.id, item.body, CASE MOD(user_row.id, 3) WHEN 0 THEN 'https://images.unsplash.com/photo-1512820790803-83ca734da794?auto=format&fit=crop&w=1200&q=85' WHEN 1 THEN 'https://images.unsplash.com/photo-1495446815901-a7297e633e8d?auto=format&fit=crop&w=1200&q=85' ELSE NULL END, v_listing_id FROM seed_users user_row WHERE user_row.email = item.email AND NOT EXISTS (SELECT 1 FROM community_stories story WHERE story.user_id = user_row.id AND story.body = item.body);
  END LOOP;
  INSERT INTO user_follows (follower_id, followed_id) SELECT follower.id, followed.id FROM seed_users follower CROSS JOIN seed_users followed WHERE follower.id <> followed.id ON CONFLICT DO NOTHING;
  INSERT INTO community_listing_likes (listing_id, user_id) SELECT listing.id, liker.id FROM seed_listings listing JOIN seed_users liker ON liker.id <> listing.user_id WHERE MOD(listing.id + liker.id, 4) = 0 ON CONFLICT DO NOTHING;
  INSERT INTO community_story_likes (story_id, user_id) SELECT story.id, liker.id FROM community_stories story JOIN seed_users author ON author.id = story.user_id JOIN seed_users liker ON liker.id <> author.id WHERE MOD(story.id + liker.id, 3) = 0 ON CONFLICT DO NOTHING;
  INSERT INTO community_comments (user_id, listing_id, body) SELECT commenter.id, listing.id, CASE MOD(listing.id, 5) WHEN 0 THEN 'Me interesa para el próximo encuentro. ¿Podés contar si tiene marcas o dedicatorias?' WHEN 1 THEN 'Gran elección: puedo acercarme al rincón y llevar otra propuesta para comparar.' WHEN 2 THEN 'Lo sumo a mi lista. Me gusta que la publicación indique estado y forma de coordinar.' WHEN 3 THEN 'Qué buena excusa para conversar; si sigue disponible, me anoto.' ELSE 'Lo vi en el mapa y me dieron ganas de pasar por ese rincón esta semana.' END FROM seed_listings listing JOIN LATERAL (SELECT id FROM seed_users WHERE id <> listing.user_id ORDER BY id LIMIT 1) commenter ON true WHERE NOT EXISTS (SELECT 1 FROM community_comments existing WHERE existing.user_id = commenter.id AND existing.listing_id = listing.id);
END $seed_social$;

DO $seed_conversations$
DECLARE item RECORD; v_conversation_id BIGINT; v_sequence BIGINT; v_book_id INTEGER; v_book_title TEXT; v_book_author TEXT; v_cover_url TEXT; v_client_prefix TEXT;
BEGIN
  FOR item IN SELECT a.email AS email_a, a.id AS user_a, b.email AS email_b, b.id AS user_b, regexp_replace(a.email, '@.*$', '') || '-' || regexp_replace(b.email, '@.*$', '') AS key FROM seed_users a JOIN seed_users b ON a.email < b.email
  LOOP
    SELECT c.id INTO v_conversation_id FROM conversations c WHERE EXISTS (SELECT 1 FROM conversation_participants p WHERE p.conversation_id = c.id AND p.user_id = item.user_a) AND EXISTS (SELECT 1 FROM conversation_participants p WHERE p.conversation_id = c.id AND p.user_id = item.user_b) AND (SELECT COUNT(*) FROM conversation_participants p WHERE p.conversation_id = c.id) = 2 LIMIT 1;
    IF v_conversation_id IS NULL THEN INSERT INTO conversations DEFAULT VALUES RETURNING id INTO v_conversation_id; INSERT INTO conversation_participants (conversation_id, user_id) VALUES (v_conversation_id, item.user_a), (v_conversation_id, item.user_b); END IF;
    INSERT INTO seed_conversations (key, id, user_a, user_b) VALUES (item.key, v_conversation_id, item.user_a, item.user_b) ON CONFLICT (key) DO UPDATE SET id = EXCLUDED.id, user_a = EXCLUDED.user_a, user_b = EXCLUDED.user_b;
    v_client_prefix := 'local-demo-' || item.key;
    SELECT book.id, book.title, book.author, book.cover_url INTO v_book_id, v_book_title, v_book_author, v_cover_url FROM seed_listings listing JOIN books book ON book.id = listing.book_id WHERE listing.user_id = item.user_a ORDER BY listing.id LIMIT 1;
    IF NOT EXISTS (SELECT 1 FROM messages WHERE conversation_id = v_conversation_id AND client_key = v_client_prefix || '-1') THEN UPDATE conversations SET last_message_sequence = last_message_sequence + 1, updated_at = NOW() WHERE id = v_conversation_id RETURNING last_message_sequence INTO v_sequence; INSERT INTO messages (conversation_id, sender_id, sequence, client_key, body, attachment_metadata) VALUES (v_conversation_id, item.user_a, v_sequence, v_client_prefix || '-1', 'Hola, vi que también participás en EntreLibros. ¿Te interesa conversar sobre este libro y pensar una propuesta?', jsonb_build_object('kind','book','bookId',v_book_id::TEXT,'title',v_book_title,'author',v_book_author,'coverUrl',v_cover_url)); END IF;
    IF NOT EXISTS (SELECT 1 FROM messages WHERE conversation_id = v_conversation_id AND client_key = v_client_prefix || '-2') THEN UPDATE conversations SET last_message_sequence = last_message_sequence + 1, updated_at = NOW() WHERE id = v_conversation_id RETURNING last_message_sequence INTO v_sequence; INSERT INTO messages (conversation_id, sender_id, sequence, client_key, body) VALUES (v_conversation_id, item.user_b, v_sequence, v_client_prefix || '-2', '¡Sí! Me gusta la propuesta. Revisemos el estado, elegimos un rincón y confirmamos antes de encontrarnos.'); END IF;
    UPDATE conversation_participants SET last_read_sequence = CASE WHEN user_id = item.user_a THEN 1 ELSE 0 END WHERE conversation_id = v_conversation_id;
    INSERT INTO message_drafts (conversation_id, author_id, body, revision) VALUES (v_conversation_id, item.user_a, 'Tengo otra opción para el intercambio; te comparto foto y coordinamos el horario.', 1) ON CONFLICT (conversation_id, author_id) DO UPDATE SET body = EXCLUDED.body, revision = message_drafts.revision + 1, updated_at = NOW();
  END LOOP;
END $seed_conversations$;

DO $seed_agreements$
DECLARE item RECORD; v_agreement_id BIGINT; v_version INTEGER; v_proposer_listing INTEGER; v_participant_listing INTEGER; v_state TEXT;
BEGIN
  FOR item IN SELECT conversation.id, conversation.user_a, conversation.user_b, conversation.key, ROW_NUMBER() OVER (ORDER BY conversation.key) AS position FROM seed_conversations conversation ORDER BY conversation.key LIMIT 12
  LOOP
    v_state := CASE MOD(item.position, 5) WHEN 1 THEN 'proposed' WHEN 2 THEN 'partially_confirmed' WHEN 3 THEN 'confirmed' WHEN 4 THEN 'completed' ELSE 'cancelled' END;
    SELECT id INTO v_proposer_listing FROM seed_listings WHERE user_id = item.user_a ORDER BY id LIMIT 1; SELECT id INTO v_participant_listing FROM seed_listings WHERE user_id = item.user_b ORDER BY id LIMIT 1;
    INSERT INTO exchange_agreements (conversation_id, proposer_id, participant_id, state, current_version) VALUES (item.id, item.user_a, item.user_b, v_state, 1) ON CONFLICT (conversation_id) DO UPDATE SET state = EXCLUDED.state, updated_at = NOW() RETURNING id, current_version INTO v_agreement_id, v_version;
    INSERT INTO exchange_agreement_versions (agreement_id, version, actor_id, state, details) VALUES (v_agreement_id, v_version, item.user_a, v_state, jsonb_build_object('meetingPoint','Rincón de Lectura Chacarita','area','Buenos Aires','date','2026-09-26','time','18:30','note','Encuentro acordado desde la conversación local')) ON CONFLICT (agreement_id, version) DO NOTHING;
    INSERT INTO exchange_agreement_items (agreement_id, version, listing_id, owner_id) VALUES (v_agreement_id, v_version, v_proposer_listing, item.user_a), (v_agreement_id, v_version, v_participant_listing, item.user_b) ON CONFLICT DO NOTHING;
    INSERT INTO exchange_agreement_acceptances (agreement_id, version, user_id) SELECT v_agreement_id, v_version, item.user_a WHERE v_state IN ('partially_confirmed','confirmed','completed') ON CONFLICT DO NOTHING;
    INSERT INTO exchange_agreement_acceptances (agreement_id, version, user_id) SELECT v_agreement_id, v_version, item.user_b WHERE v_state IN ('confirmed','completed') ON CONFLICT DO NOTHING;
    INSERT INTO agreement_events (agreement_id, version, actor_id, event_type) SELECT v_agreement_id, v_version, item.user_a, CASE v_state WHEN 'proposed' THEN 'proposal' WHEN 'confirmed' THEN 'confirm' WHEN 'completed' THEN 'complete' WHEN 'cancelled' THEN 'cancel' ELSE 'accept' END WHERE NOT EXISTS (SELECT 1 FROM agreement_events event WHERE event.agreement_id = v_agreement_id AND event.version = v_version);
    IF v_state IN ('completed','cancelled') THEN INSERT INTO exchange_agreement_outcomes (agreement_id, user_id, outcome, reason) VALUES (v_agreement_id, item.user_a, CASE WHEN v_state = 'completed' THEN 'completed' ELSE 'not_completed' END, CASE WHEN v_state = 'completed' THEN 'Intercambio realizado y registrado en la demo local.' ELSE 'No coincidieron los horarios; la conversación puede continuar.' END) ON CONFLICT (agreement_id, user_id) DO UPDATE SET outcome = EXCLUDED.outcome, reason = EXCLUDED.reason; END IF;
    INSERT INTO notifications (recipient_id, kind, entity_id, title_key, body_key, data, idempotency_key) VALUES (item.user_b, 'agreement', v_agreement_id::TEXT, 'notifications.agreement.' || v_state, 'notifications.agreement.confirmedWith', jsonb_build_object('state',v_state,'participantName',(SELECT name FROM users WHERE id = item.user_a)), 'local-demo-agreement-' || item.key) ON CONFLICT (idempotency_key) DO NOTHING;
  END LOOP;
END $seed_agreements$;

INSERT INTO analytics_events (event_type, actor_id, entity_type, entity_id, metadata, occurred_at, idempotency_key)
SELECT event.event_type, actor.id, event.entity_type, event.entity_id, event.metadata, event.occurred_at, event.idempotency_key
FROM (VALUES
  ('listing_published','test@entrelibros.com','listing','test-first-listing','{}'::JSONB,NOW() - INTERVAL '3 hours','local-demo-analytics-test'),('listing_published','lucia@entrelibros.com','listing','lucia-first-listing','{}'::JSONB,NOW() - INTERVAL '1 day','local-demo-analytics-lucia'),('contact_started','martin@entrelibros.com','conversation','martin-test','{}'::JSONB,NOW() - INTERVAL '22 hours','local-demo-analytics-martin'),('agreement_created','sofia@entrelibros.com','conversation','sofia-test','{}'::JSONB,NOW() - INTERVAL '16 hours','local-demo-analytics-sofia'),('agreement_confirmed','clara@entrelibros.com','agreement','clara-test','{}'::JSONB,NOW() - INTERVAL '8 hours','local-demo-analytics-clara'),('outcome_recorded','tomas@entrelibros.com','agreement','tomas-test','{"outcome":"completed"}'::JSONB,NOW() - INTERVAL '2 hours','local-demo-analytics-tomas')
) AS event(event_type, actor_email, entity_type, entity_id, metadata, occurred_at, idempotency_key)
JOIN seed_users actor ON actor.email = event.actor_email
ON CONFLICT (idempotency_key) DO NOTHING;

COMMIT;
